/* ============================================================
   수업 도판의 대체 글(alt)과 작품 설명 (2026-09-29 생성, 손으로 고쳐도 된다)
   ------------------------------------------------------------
   시각장애 학생과 스크린리더 사용자를 위한 말 설명. 도판마다 두 가지를 둔다.
     alt: 무엇의 이미지인지 한 문장(90자 이내). <img alt>로 쓴다(캡션과 겹치지 않게 보이는 것 위주)
     desc: 긴 설명. 기본 정보 → 전체 모습 → 세부(위치 말: 왼쪽 위, 가운데…) → 색·빛·질감 → 수업에서 볼 점
     touch: (있으면) 재료에 맞는 촉각 비유 한 문장
   작성 방법: Art Beyond Sight의 말 설명 지침, 쿠퍼 휴잇 이미지 설명 지침을 따르고, 캡션·SOURCES.md에 없는 사실
   (크기·연도·소장처)은 쓰지 않았다. 도판을 보며 쓴 초안을 다른 검토자가 도판과 캡션에 대조해 고친 검증본만 싣는다.
   설계서: 다양한_학습자_지원_설계.md §4.2. 새 도판(설명 없음)은 alt가 캡션 제목으로 대신되고 설명은 그리지 않는다.
   ============================================================ */
